/* 1. Kill ALL outlines & borders everywhere inside the section */
.custom-gradient,
.custom-gradient *,
.custom-gradient::before,
.custom-gradient::after {
  border: 3 !important;
  outline: 0 !important;
  outline-offset: 0 !important;
  box-shadow: none !important;
}

/* 2. Fix Elementor section + inner section layers */
.custom-gradient {
  position: relative !important;
  overflow: hidden !important;
}

/* 3. Force overlay to NOT create edges */
.custom-gradient::before {
  content: "";
  position: absolute;
  top: -1px;   /* IMPORTANT */
  left: -1px;  /* IMPORTANT */
  right: -1px; /* IMPORTANT */
  bottom: -1px;/* IMPORTANT */
  background: linear-gradient(
    90deg,
    rgba(0,0,0,0.95) 0%,
    rgba(9,9,9,0.85) 40%,
    rgba(90,31,31,0.25) 70%,
    rgba(90,31,31,0.05) 100%
  );
  pointer-events: none;
  z-index: 0;
}

/* 4. Keep content above overlay */
.custom-gradient > .elementor-container,
.custom-gradient > .elementor-container * {
  position: relative;
  z-index: 1;
}

